{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "Organization",
      "name": "SumHealth",
      "url": "https://sumhealth.org"
    },
    {
      "@type": "WebSite",
      "name": "SumHealth",
      "url": "https://sumhealth.org",
      "potentialAction": {
        "@type": "SearchAction",
        "target": "https://sumhealth.org/search?q={search_term_string}",
        "query-input": "required name=search_term_string"
      }
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Ready to see the data for yourself?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pricing intelligencefor every providerpatient"
          }
        },
        {
          "@type": "Question",
          "name": "So why doesn’t this data already exist?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The part where somebody has to actually build it"
          }
        },
        {
          "@type": "Question",
          "name": "Is Your Practice Experiencing Any of These Challenges?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Rate Disparity"
          }
        },
        {
          "@type": "Question",
          "name": "Ready to Strengthen Your Financial Foundation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pricing intelligencefor every providerpatient"
          }
        },
        {
          "@type": "Question",
          "name": "What is a healthcare cash price?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A healthcare cash price is the amount a hospital or provider lists for a patient paying directly rather than billing an insurance plan. It can differ from an insurer-negotiated rate and usually does not count toward an insurance deductible."
          }
        },
        {
          "@type": "Question",
          "name": "How can I compare healthcare cash prices near me?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Enter a procedure name or CPT code and a ZIP code in the SumHealth Healthcare Cash Price Checker. The free tool sends you to matching hospital and provider prices so you can compare nearby options before scheduling care."
          }
        },
        {
          "@type": "Question",
          "name": "How much does SumHealth cost for individual users?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "SumHealth's cash price checker is completely free for individual users. There are no sign-ups, no credit cards, and no hidden fees. You can search hospital prices and provider cash prices as many times as you like, at no cost."
          }
        },
        {
          "@type": "Question",
          "name": "Is there a paid version of SumHealth?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. SumHealth offers premium plans for healthcare organizations, payers, and enterprises who need API access, bulk data exports, and advanced analytics through our BenchMarks platform. Contact us to learn more."
          }
        },
        {
          "@type": "Question",
          "name": "Do I need to provide an email address to sign up for SumHealth?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Our free cash price checker requires no sign-up or account creation. Simply enter a procedure and your zip code to start searching immediately."
          }
        },
        {
          "@type": "Question",
          "name": "How often is pricing data updated?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "SumHealth processes hospital Machine-Readable Files and provider-submitted cash prices. The searchable dataset is refreshed monthly as new source data becomes available."
          }
        },
        {
          "@type": "Question",
          "name": "How many hospitals are available on SumHealth's Price Transparency Tool?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Our database currently covers over 5,000 hospitals across all 50 states, including major health systems, community hospitals, and specialty facilities. We are also adding provider cash prices, and coverage keeps expanding as new data becomes available."
          }
        },
        {
          "@type": "Question",
          "name": "What is the SumHealth provider directory?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The live SumHealth provider directory lets you explore participating providers and their published cash prices in one place. Open the directory to browse available providers."
          }
        },
        {
          "@type": "Question",
          "name": "Can I use the platform for my entire organization?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. SumHealth offers enterprise licensing for organizations that need team access, custom integrations, or white-label deployments. Reach out to our team to discuss options."
          }
        },
        {
          "@type": "Question",
          "name": "What makes your data different from publicly available information?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Hospital Machine-Readable Files are public but difficult to compare in their raw form. SumHealth normalizes and structures those files, then combines them with a growing set of provider-submitted cash prices so people can search the information by procedure and location."
          }
        },
        {
          "@type": "Question",
          "name": "Are the prices shown guaranteed estimates?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Published prices can change and may not include every professional fee, facility fee, or patient-specific circumstance. Use the checker as a comparison starting point and confirm the complete cash price with the hospital or provider before receiving care."
          }
        },
        {
          "@type": "Question",
          "name": "3. Need help?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "See what is in the CSV"
          }
        },
        {
          "@type": "Question",
          "name": "What is healthcare price transparency?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Healthcare price transparency is the requirement that hospitals and health insurers publicly disclose the actual prices of care — including negotiated rates, cash prices, and standard charges — so patients and purchasers can compare costs before receiving care. In the U.S. it is anchored by the CMS Hospital Price Transparency rule (effective January 1, 2021) and the Transparency in Coverage rule for health plans (machine-readable files effective July 1, 2022)."
          }
        },
        {
          "@type": "Question",
          "name": "What is a machine-readable file (MRF)?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A machine-readable file is a structured data file (typically JSON or CSV) that hospitals and health plans must publish containing their standard charges or negotiated rates. Hospital MRFs list gross charges, discounted cash prices, and payer-specific negotiated rates; payer MRFs list in-network negotiated rates and out-of-network allowed amounts for covered items and services."
          }
        },
        {
          "@type": "Question",
          "name": "What happens if a hospital does not comply with price transparency rules?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "CMS can issue warning letters, require corrective action plans, and impose civil monetary penalties of up to $5,500 per day for the largest hospitals — over $2 million per year of non-compliance. CMS issued its first fines in June 2022 to two Georgia hospitals totaling nearly $1.1 million, and enforcement has accelerated since."
          }
        },
        {
          "@type": "Question",
          "name": "When did healthcare price transparency become law?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The foundation was laid in 2010 by Section 2718(e) of the Affordable Care Act, which required hospitals to publish standard charges. A 2019 executive order led CMS to finalize the Hospital Price Transparency rule, effective January 1, 2021, followed by the No Surprises Act (January 1, 2022) and the Transparency in Coverage rule for payers (July 1, 2022)."
          }
        },
        {
          "@type": "Question",
          "name": "What is healthcareprice transparency?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The Opaque Era"
          }
        },
        {
          "@type": "Question",
          "name": "Is Your Hospital at Risk?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Don't Wait for CMS to Come Knocking"
          }
        },
        {
          "@type": "Question",
          "name": "Ready to Build Something?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pricing intelligencefor every providerpatient"
          }
        },
        {
          "@type": "Question",
          "name": "Ready to see what you'vereally been charged?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pricing intelligencefor every providerpatient"
          }
        },
        {
          "@type": "Question",
          "name": "Who is this not a fit for?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "This is not a fit if you: Are looking for a specific drug and a prescription with no evaluation Need urgent or emergency care Are hoping to bill insurance for the visits Want a guarantee before anyone has looked at your labs That last one is not us being difficult. A provider who will promise you a prescription before evaluating you is not a provider you want."
          }
        },
        {
          "@type": "Question",
          "name": "Will I get a prescription?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Only if an independent licensed provider evaluates you and determines it is appropriate. Nothing is guaranteed, and any provider promising otherwise is a red flag."
          }
        },
        {
          "@type": "Question",
          "name": "How much does it cost?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "This is a cash pay service. The provider's practice sets its own pricing and bills you directly. SumHealth does not set prices and does not take a share of what you pay for care. We do not bill insurance. No claims, no deductibles, no surprise explanation of benefits six weeks later. You will know the cost before anything happens. You may be able to use HSA/FSA. Many patients do. Check with your plan administrator, since rules vary. Some labs may be covered. If you choose to run them through your own insurance plan, the provider can talk you through that option during evaluation."
          }
        },
        {
          "@type": "Question",
          "name": "Why no insurance?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Insurance coverage drives what gets tested and discussed. Cash pay keeps that decision between you and your provider. It also means no prior authorization delays."
          }
        },
        {
          "@type": "Question",
          "name": "Is this legitimate telehealth?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "If you are matched for telehealth care, the independent practice is responsible for confirming that its licensed clinician can legally care for you in North Carolina."
          }
        },
        {
          "@type": "Question",
          "name": "Who sees my information?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "What you submit goes to SumHealth and to the independent medical practice we introduce you to, and only with your explicit consent. We do not sell your information."
          }
        },
        {
          "@type": "Question",
          "name": "Have Questions? We've Got Answers",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Company"
          }
        },
        {
          "@type": "Question",
          "name": "Ready to give your members a price they can trust?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pricing intelligencefor every providerpatient"
          }
        }
      ]
    }
  ]
}
